// Generated by integrations/schedule-import/build-nightly.cjs. Do not edit in n8n.
const randomUUID = () => crypto.randomUUID();

// This module also runs in an n8n Code node. Keep it free of Node dependencies.
const SOURCE_SYSTEM = "wieik-v1";
const FIELDS = ["faculty", "date", "start_time", "duration_min", "subject",
  "instructor", "room", "group", "type", "status"];
const TYPES = { W: "Wykład", L: "Labolatorium", Lab: "Labolatorium",
  Lk: "Labolatorium Komputerowe", P: "Projekt", Lek: "Lektorat",
  C: "Ćwiczenia", S: "Seminarium" };
const DAY_MS = 86400000;
const MAX_ROWS = 50000;

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function isoDate(value) {
  assert(typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value), "Invalid ISO date");
  const timestamp = Date.parse(`${value}T00:00:00Z`);
  assert(Number.isFinite(timestamp) && new Date(timestamp).toISOString().slice(0, 10) === value,
    "Invalid calendar date");
  return value;
}

function time(value) {
  assert(typeof value === "string" && /^(?:[01]\d|2[0-3]):[0-5]\d(?::00)?$/.test(value),
    "Invalid start time (whole minutes required)");
  return value.length === 5 ? `${value}:00` : value;
}

function nullableText(value, field) {
  assert(value === null || (typeof value === "string" && value.length <= 4096), `Invalid ${field}`);
  return value;
}

function validateFields(row) {
  isoDate(row.date);
  time(row.start_time);
  assert(Number.isInteger(row.duration_min) && row.duration_min > 0 && row.duration_min <= 1440,
    "Invalid duration");
  assert(typeof row.subject === "string" && row.subject.trim().length > 0 && row.subject.length <= 4096,
    "Invalid subject");
  for (const field of ["faculty", "instructor", "room", "group", "type", "status"])
    nullableText(row[field], field);
}

function envelope(payload, db) {
  assert(payload && payload.ok === true && payload.db === db && Array.isArray(payload.data),
    `Invalid or unsuccessful ${db} snapshot`);
  assert(typeof payload.revision === "string" && payload.revision.length > 0 &&
    Number.isFinite(payload.mtime), `Missing ${db} snapshot metadata`);
  assert(payload.data.length <= MAX_ROWS, `${db} snapshot too large`);
  return payload.data;
}

function datesBetween(from, to, stepDays = 1) {
  isoDate(from); isoDate(to);
  const start = Date.parse(`${from}T00:00:00Z`);
  const end = Date.parse(`${to}T00:00:00Z`);
  assert(start <= end && end - start <= 732 * DAY_MS, "Invalid or excessive date range");
  const dates = [];
  for (let timestamp = start; timestamp <= end; timestamp += stepDays * DAY_MS)
    dates.push(new Date(timestamp).toISOString().slice(0, 10));
  return dates;
}

function candidateKey(parts) {
  // Candidate identity, NOT a guarantee across moved dates or renamed groups.
  return JSON.stringify(parts);
}

function transformSnapshots(schedule, blocks) {
  const series = envelope(schedule, "stac");
  const daysOff = envelope(blocks, "block");
  assert(series.length > 0, "Empty schedule requires investigation; no import generated");
  const freeDays = new Map();
  for (const block of daysOff) {
    assert(block && typeof block === "object", "Invalid block");
    // The supplied importer only supports global blocks. Fail instead of losing a scoped block.
    assert(block.scope === "all", "Scoped blocks require an explicit implementation");
    const label = block.label || "Dzień wolny";
    assert(typeof label === "string" && label.length <= 4096, "Invalid block label");
    const dates = block.date ? [isoDate(block.date)] : datesBetween(block.from, block.to);
    for (const date of dates) {
      assert(!freeDays.has(date) || freeDays.get(date) === label, "Conflicting day-off labels");
      freeDays.set(date, label);
      assert(freeDays.size <= MAX_ROWS, "Too many days off");
    }
  }

  const rows = [];
  const warnings = [];
  const seriesIds = new Set();
  const keys = new Set();
  const push = (row) => {
    validateFields(row);
    assert(!keys.has(row.source_key), "Duplicate source occurrence");
    keys.add(row.source_key);
    rows.push(row);
    assert(rows.length <= MAX_ROWS, "Expanded snapshot too large");
  };
  for (const event of series) {
    assert(event && typeof event.id === "string" && event.id.length > 0 && event.id.length <= 256,
      "Missing source series id");
    assert(!seriesIds.has(event.id), "Duplicate source series id");
    seriesIds.add(event.id);
    assert(Number.isInteger(event.intervalWeeks) && event.intervalWeeks > 0 && event.intervalWeeks <= 52,
      "Invalid recurrence interval");
    const dates = new Set(datesBetween(event.startDate, event.endDate, event.intervalWeeks * 7));
    // The API uses [] for an empty override map, and objects for nonempty maps.
    const overrides = Array.isArray(event.overrides) && event.overrides.length === 0 ? {} : event.overrides;
    assert(overrides && typeof overrides === "object" && !Array.isArray(overrides), "Invalid overrides");
    assert(Object.keys(overrides).length <= MAX_ROWS, "Too many source overrides");
    assert(Array.isArray(event.excludedDates) && event.excludedDates.length <= MAX_ROWS, "Invalid excludedDates");
    const excluded = new Set(event.excludedDates.map(isoDate));
    for (const [date, patch] of Object.entries(overrides)) {
      isoDate(date);
      assert(patch && typeof patch === "object" && !Array.isArray(patch), "Invalid source override");
      for (const flag of ["_add", "cancelled"])
        if (Object.hasOwn(patch, flag)) assert(typeof patch[flag] === "boolean", `Invalid ${flag}`);
      // Removed additions can remain in the API as _add:false,cancelled:true
      // outside the current recurrence. Keep a tombstone instead of discarding it.
      if (patch._add === true || patch.cancelled === true) dates.add(date);
      else if (!dates.has(date)) {
        // Editing a date then shortening a series can leave _add:false,
        // cancelled:false metadata. It is not a new active occurrence.
        // Any old active database row still requires explicit retirement.
        warnings.push({ kind: "orphan_override", series_id: event.id, date });
        assert(warnings.length <= MAX_ROWS, "Too many orphan overrides");
      }
    }
    for (const date of [...dates].sort()) {
      const patch = overrides[date] || {};
      const field = (name) => Object.hasOwn(patch, name) ? patch[name] : event[name];
      const groupValue = nullableText(field("group"), "group");
      // Preserve the existing per-group model, including single and NULL groups.
      // Changing group membership will be reviewed by the reconciliation planner.
      const groups = groupValue === null ? [null] :
        [...new Set(groupValue.split(/[,/]/).map((value) => value.trim()).filter(Boolean))];
      if (groups.length === 0) groups.push("");
      const cancelled = patch.cancelled === true ||
        (excluded.has(date) && patch._add !== true) || freeDays.has(date);
      for (const group of groups) {
        const prefix = group === null ? null : group.replace(/\d+$/, "").trim();
        push({
          source_system: SOURCE_SYSTEM,
          source_key: candidateKey(["stac", event.id, date, group]),
          faculty: field("faculty"), date, start_time: time(field("startTime")),
          duration_min: field("durationMin"), subject: field("eventType"),
          instructor: field("instructor"), room: field("room"), group,
          type: prefix === null || prefix === "" ? null : TYPES[prefix] || prefix,
          // Retain cancelled source records; existing readers already hide this status.
          status: cancelled ? "nieaktywne" : "aktywne",
        });
      }
    }
  }
  for (const [date, label] of freeDays) push({
    source_system: SOURCE_SYSTEM, source_key: candidateKey(["block", date]),
    faculty: "all", date, start_time: "07:00:00", duration_min: 900, subject: label,
    instructor: null, room: null, group: null, type: null, status: "wolne",
  });
  rows.sort((a, b) => a.source_key.localeCompare(b.source_key, "en"));
  return { protocol: 1, source_system: SOURCE_SYSTEM,
    revisions: { stac: schedule.revision, block: blocks.revision }, warnings, rows };
}





const COLUMNS = ["id", ...FIELDS, "source_system", "source_key"];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

function canonicalRow(row, sourceRequired = false) {
  assert(row && typeof row === "object", "Invalid database row");
  assert(typeof row.id === "string" && UUID.test(row.id), "Invalid event UUID");
  const result = Object.fromEntries(COLUMNS.map((field) => [field, row[field]]));
  result.start_time = time(result.start_time);
  result.source_system ??= null;
  result.source_key ??= null;
  validateFields(result);
  assert((result.source_system === null && result.source_key === null) ||
    (typeof result.source_system === "string" && result.source_system.length > 0 &&
      typeof result.source_key === "string" && result.source_key.length > 0), "Incomplete source identity");
  if (sourceRequired) assert(result.source_system === SOURCE_SYSTEM, "Unexpected source system");
  return result;
}

function createPlan(snapshot, existingRows, decisions = {}, makeUUID = randomUUID) {
  assert(snapshot?.protocol === 1 && snapshot.source_system === SOURCE_SYSTEM &&
    Array.isArray(snapshot.rows) && snapshot.rows.length > 0, "Invalid normalized snapshot");
  assert(Array.isArray(existingRows), "Expected a complete events export array");
  for (const key of Object.keys(decisions))
    assert(["matches", "create", "retire", "retain_unmanaged"].includes(key), `Unknown decision: ${key}`);
  const matches = decisions.matches || [];
  const creations = decisions.create || [];
  const retirements = decisions.retire || [];
  const retained = decisions.retain_unmanaged || [];
  for (const list of [matches, creations, retirements, retained])
    assert(Array.isArray(list), "Decision lists must be arrays");
  const baseline = existingRows.map((row) => canonicalRow(row)).sort((a, b) => a.id < b.id ? -1 : 1);
  const byId = new Map();
  const byKey = new Map();
  for (const row of baseline) {
    assert(!byId.has(row.id), "Duplicate database UUID");
    byId.set(row.id, row);
    if (row.source_system === SOURCE_SYSTEM) {
      assert(!byKey.has(row.source_key), "Duplicate existing source key");
      byKey.set(row.source_key, row);
    }
  }
  const incoming = new Map();
  for (const row of snapshot.rows) {
    assert(row.source_system === SOURCE_SYSTEM && typeof row.source_key === "string" &&
      row.source_key.length > 0 && row.source_key.length <= 2048, "Invalid candidate source key");
    assert(!Object.hasOwn(row, "id"), "Source text IDs must not be used as UUIDs");
    validateFields(row);
    assert(["aktywne", "nieaktywne", "wolne"].includes(row.status), "Invalid imported status");
    assert(!incoming.has(row.source_key), "Duplicate incoming source key");
    incoming.set(row.source_key, row);
  }

  const mappings = new Map();
  const mappedIds = new Set();
  for (const match of matches) {
    assert(match && Object.keys(match).length === 2 &&
      Object.hasOwn(match, "source_key") && Object.hasOwn(match, "event_id"), "Invalid match decision");
    const old = byId.get(match.event_id);
    assert(old && incoming.has(match.source_key), "Match must reference an existing UUID and incoming key");
    assert(old.source_system === null || old.source_system === SOURCE_SYSTEM, "Cannot adopt another source");
    assert(!mappings.has(match.source_key) && !mappedIds.has(old.id), "Duplicate match decision");
    mappings.set(match.source_key, old);
    mappedIds.add(old.id);
  }
  const create = new Set(creations);
  const retire = new Set(retirements);
  const keep = new Set(retained);
  assert(create.size === creations.length && retire.size === retirements.length &&
    keep.size === retained.length, "Duplicate decision");
  for (const key of create)
    assert(incoming.has(key) && (!byKey.has(key) || mappedIds.has(byKey.get(key).id)) &&
      !mappings.has(key), "Invalid create decision");
  for (const id of retire) {
    const old = byId.get(id);
    assert(old && (old.source_system === null || old.source_system === SOURCE_SYSTEM) &&
      !mappedIds.has(id), "Invalid retire decision");
  }
  for (const id of keep)
    assert(byId.get(id)?.source_system === null && !retire.has(id) && !mappedIds.has(id),
      "Invalid retain_unmanaged decision");

  const blockers = [];
  const changes = [];
  const used = new Set();
  for (const [key, row] of incoming) {
    const old = mappings.get(key) || (create.has(key) ? null : byKey.get(key));
    if (old) {
      assert(!used.has(old.id), "One UUID cannot represent two incoming occurrences; map both explicitly");
      assert(!retire.has(old.id), "Cannot retire a matched occurrence");
      used.add(old.id);
      const next = canonicalRow({ ...row, id: old.id }, true);
      if (JSON.stringify(next) !== JSON.stringify(old)) changes.push(next);
    } else if (create.has(key)) {
      const next = canonicalRow({ ...row, id: makeUUID() }, true);
      assert(!byId.has(next.id) && !used.has(next.id), "Generated duplicate UUID");
      used.add(next.id);
      changes.push(next);
    } else blockers.push({ kind: "unmapped_occurrence", source_key: key });
  }
  for (const row of baseline) {
    if (used.has(row.id)) continue;
    if (retire.has(row.id)) {
      changes.push({ ...row, source_system: SOURCE_SYSTEM,
        source_key: row.source_key || JSON.stringify(["legacy", row.id]), status: "nieaktywne" });
    } else if (row.source_system === SOURCE_SYSTEM) {
      // An already retired row remains available for reappearance with the same UUID.
      if (row.status !== "nieaktywne") blockers.push({ kind: "missing_occurrence", event_id: row.id,
        source_key: row.source_key });
    } else if (row.source_system === null && !keep.has(row.id)) {
      blockers.push({ kind: "unmanaged_existing_event", event_id: row.id });
    }
  }
  const finalKeys = new Set();
  const finalRows = new Map(baseline.map((row) => [row.id, row]));
  for (const row of changes) finalRows.set(row.id, row);
  for (const row of finalRows.values()) if (row.source_system === SOURCE_SYSTEM) {
    assert(!finalKeys.has(row.source_key), "Two UUIDs would share a source key; review duplicate mappings");
    finalKeys.add(row.source_key);
  }
  return { ready: blockers.length === 0, blockers,
    summary: { incoming: incoming.size, existing: baseline.length,
      inserted: changes.filter((row) => !byId.has(row.id)).length,
      updated: changes.filter((row) => byId.has(row.id)).length },
    revisions: snapshot.revisions,
    warnings: snapshot.warnings || [],
    // Never emit an executable partial plan with unresolved identities.
    rpc: blockers.length ? null : { p_expected: baseline, p_changes: changes } };
}



// This module also runs in an n8n Code node. Keep it free of Node dependencies.


// Unattended policy for the nightly import. Identities that are certain apply without review: the
// same source key (room, time, instructor or status changes), new keys, and vanished classes, which
// become inactive and are never deleted. A vanished class that private rows point at is retired too,
// so one user's data never stops the import for everyone; it is listed in `referenced_retired` for an
// informational e-mail and its private rows stay attached to the same UUID. Only a row outside the
// importer or a mass disappearance (a likely partial upstream answer) keeps the last good state.
function createNightlyPlan(snapshot, existingRows, referencedIds = [], limits = {}) {
  const { minRetireAlarm = 50, maxRetireShare = 0.1 } = limits;
  const referenced = new Set(referencedIds);
  const incomingKeys = new Set(snapshot.rows.map((row) => row.source_key));
  const known = new Set();
  const retire = [];
  const referencedRetired = [];
  let active = 0;
  for (const row of existingRows) {
    if (row.source_system !== SOURCE_SYSTEM) continue;
    known.add(row.source_key);
    if (row.status === "nieaktywne") continue;
    active += 1;
    if (incomingKeys.has(row.source_key)) continue;
    retire.push(row.id);
    if (referenced.has(row.id)) referencedRetired.push({ event_id: row.id, faculty: row.faculty, date: row.date,
      start_time: row.start_time, subject: row.subject, group: row.group });
  }
  const create = [...incomingKeys].filter((key) => !known.has(key));
  const plan = createPlan(snapshot, existingRows, { create, retire });
  const blockers = [...plan.blockers];
  const limit = Math.max(minRetireAlarm, Math.floor(active * maxRetireShare));
  if (retire.length > limit) blockers.push({ kind: "mass_disappearance", retired: retire.length, limit });
  return { ...plan, ready: blockers.length === 0, blockers, rpc: blockers.length ? null : plan.rpc,
    referenced_retired: referencedRetired,
    nightly: { created: create.length, retired: retire.length, referenced_retired: referencedRetired.length,
      updated: plan.summary.updated - retire.length, active_before: active } };
}


const payloads = $input.all().map(item => item.json);
const schedule = payloads.filter(p => p.db === 'stac');
const blocks = payloads.filter(p => p.db === 'block');
const database = payloads.filter(p => Array.isArray(p.events) && Array.isArray(p.referenced));
assert(schedule.length === 1 && blocks.length === 1 && database.length === 1, 'Expected two source snapshots and one database export');
const plan = createNightlyPlan(transformSnapshots(schedule[0], blocks[0]), database[0].events, database[0].referenced);
const action = !plan.ready ? 'blocked' : plan.rpc.p_changes.length ? 'apply' : 'none';
return [{ json: { action, nightly: plan.nightly, blockers: plan.blockers.slice(0, 50), blocker_count: plan.blockers.length,
  referenced_retired: plan.referenced_retired.slice(0, 50), warnings: plan.warnings, revisions: plan.revisions,
  p_expected: plan.rpc ? JSON.stringify(plan.rpc.p_expected) : '[]',
  p_changes: plan.rpc ? JSON.stringify(plan.rpc.p_changes) : '[]' } }];

const plan = $('Plan nightly import').first().json;
const result = $input.first().json.result;
// A blocked plan keeps the last good state; it still needs a decision, so the run is reported as failed.
if (plan.action === 'blocked') throw new Error('Nightly schedule import blocked (' + plan.blocker_count + '): ' +
  JSON.stringify(plan.blockers.slice(0, 5)));
return [{ json: { action: plan.action, nightly: plan.nightly, result, warnings: plan.warnings.length } }];

const plan = $('Plan nightly import').first().json;
if (plan.action !== 'apply' || !plan.nightly.referenced_retired) return [];
const lines = plan.referenced_retired.map(c => '- ' + c.faculty + ', ' + c.date + ' ' + String(c.start_time).slice(0, 5) +
  ', ' + c.subject + (c.group ? ' (' + c.group + ')' : ''));
const more = plan.nightly.referenced_retired - lines.length;
return [{ json: { count: plan.nightly.referenced_retired, list: lines.join('\n') + (more > 0 ? '\n… i ' + more + ' więcej' : '') } }];

